        return !(isNotEquals(comparison, condition) || isGreater(comparison, condition) || isSmaller(comparison, condition) || isEquals(comparison, condition));
    } catch (NullPointerException e) {
        // Log or handle the NullPointerException
        System.err.println("NullPointerException occurred: " + e.getMessage());
        return false;
    } catch (ClassCastException e) {
        // Log or handle the ClassCastException
        System.err.println("ClassCastException occurred: " + e.getMessage());
        return false;
    }
}
